package com.termux.app.workspace;
import android.app.*;import android.graphics.Rect;import android.os.Looper;import android.view.*;import android.widget.*;
import com.termux.shared.view.KeyboardUtils;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
import java.util.*;import java.util.concurrent.atomic.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=29,application=Application.class,shadows=WorkspaceEdgeGestureTest.Keyboard.class)
public class WorkspaceEdgeGestureTest {
 static boolean ime;
 @Implements(value=KeyboardUtils.class,isInAndroidSdk=false) public static class Keyboard {@Implementation protected static boolean isSoftKeyboardVisible(Activity a){return ime;}}
 Activity a;FrameLayout root;WorkspaceEdgeGesture gesture;WorkspaceSidebar menu;AtomicInteger opened=new AtomicInteger();boolean allowed=true;
 @Before public void setup(){ime=false;a=Robolectric.buildActivity(Activity.class).setup().visible().get();root=new FrameLayout(a);a.setContentView(root);root.measure(View.MeasureSpec.makeMeasureSpec(360,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(640,View.MeasureSpec.EXACTLY));root.layout(0,0,360,640);gesture=new WorkspaceEdgeGesture(a,root,()->allowed,()->{opened.incrementAndGet();menu=new WorkspaceSidebar(a);menu.section("Test");return menu;});}
 @After public void close(){gesture.close();if(menu!=null)menu.dismiss();idle();a.finish();ime=false;}
 void idle(){Shadows.shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofMillis(350));}
 boolean touch(int action,float x,float y,long t){int[] origin=new int[2];root.getLocationOnScreen(origin);MotionEvent e=MotionEvent.obtain(100,t,action,origin[0]+x,origin[1]+y,0);try{return gesture.touch(e);}finally{e.recycle();}}
 @Test public void followsFingerAndOpensOnlyOnCompletion(){assertFalse(touch(0,2,300,100));assertTrue(touch(2,70,301,200));assertEquals(1,opened.get());assertFalse(menu.dialog.isShowing());assertEquals(68-menu.panelWidth(),menu.scroll.getTranslationX(),.01);assertTrue(touch(2,150,302,300));assertEquals(148-menu.panelWidth(),menu.scroll.getTranslationX(),.01);assertTrue(touch(1,180,302,400));idle();assertTrue(menu.dialog.isShowing());menu.dialog.onBackPressed();idle();assertFalse(menu.dialog.isShowing());}
 @Test public void cancellationAndShortDragRestoreThePreviousScreen(){for(int end:new int[]{MotionEvent.ACTION_CANCEL,MotionEvent.ACTION_UP}){touch(0,2,250,100);touch(2,25,251,300);assertTrue(touch(end,25,251,600));idle();assertFalse(menu.dialog.isShowing());assertNull(root.findViewWithTag("workspace-sidebar"));}}
 @Test public void verticalScrollingRightEdgeAndSelectionNeverOpenMenu(){touch(0,2,200,100);assertFalse(touch(2,4,250,200));assertFalse(touch(1,120,250,300));touch(0,359,200,100);assertFalse(touch(2,240,201,200));touch(1,240,201,300);TextView selected=new EditText(a);selected.setText("selected text");((EditText)selected).setSelection(0,4);root.addView(selected);touch(0,2,200,100);assertFalse(touch(2,140,201,200));assertEquals(0,opened.get());}
 @Test public void imeDisablesExclusionAndCannotTurnOneGestureIntoMenuOpen(){gesture.updateExclusion();assertEquals(1,root.getSystemGestureExclusionRects().size());Rect zone=root.getSystemGestureExclusionRects().get(0);assertEquals(0,zone.left);assertTrue(zone.height()<=WorkspaceDialogs.dp(a,200));assertTrue(zone.right<=WorkspaceDialogs.dp(a,24));ime=true;gesture.updateExclusion();assertTrue(root.getSystemGestureExclusionRects().isEmpty());touch(0,2,200,100);ime=false;assertFalse(touch(2,160,201,200));assertFalse(touch(1,190,201,300));assertEquals(0,opened.get());touch(0,2,200,400);assertTrue(touch(2,160,201,500));assertTrue(touch(1,190,201,600));idle();assertTrue(menu.dialog.isShowing());}
 @Test public void x11DisabledStateRemovesExclusionAndCancelsCurrentDrag(){allowed=false;gesture.updateExclusion();assertTrue(root.getSystemGestureExclusionRects().isEmpty());touch(0,2,200,100);assertFalse(touch(2,130,201,200));assertEquals(0,opened.get());allowed=true;touch(0,2,200,300);touch(2,80,201,400);allowed=false;touch(2,130,201,500);idle();assertFalse(menu.dialog.isShowing());}
 @Test public void deliveredEdgeTouchesCanBeginAtTopAndBottomOutsideSystemBudget(){for(int y:new int[]{2,630}){touch(0,2,y,100);assertTrue(touch(2,80,y,200));touch(MotionEvent.ACTION_CANCEL,80,y,300);idle();}assertEquals(2,opened.get());}
}
